// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e18);

        // owner configures and opens the game
        vm.startPrank(address(this), address(this));
        c.AdjustBetAmounts(amount);
        c.OpenToThePublic();
        vm.stopPrank();

        // a real player (msg.sender == tx.origin) places a fresh wager
        vm.deal(actor, amount);
        vm.prank(actor, actor);
        bool ok;
        try c.wager{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.hasPlayerWagered(actor));
    }
}
